#[test]
fn seconds_clock_over_long_steps() {
    const TM3CNT_L: u32 = 0x10C;
    let mut timers = Timers::new();
    let mut irq = Irq::new();
    start(&mut timers, &mut irq, TM3CNT_L, 0, CONTROL_COUNT_UP);
    start(&mut timers, &mut irq, 0x108, 0xC000, 3);
    for _ in 0..3 * 60 {
